package net.officefloor.hq.app;

import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * {@code POST /api/projects} — add a project (name + client) and return the created row with its
 * client's NAME. Wired by {@code officefloor/rest/api/projects.POST.yml}. The client must exist; the
 * create is audited through {@link Audit}.
 */
public class ProjectsPost {

    public void service(@RequestBody NewProject body, ProjectRepository projects,
            ClientRepository clients, Audit audit, ObjectResponse<ProjectView> response) {
        String name = body.getName() == null ? "" : body.getName().trim();
        if (name.isEmpty()) {
            throw new IllegalArgumentException("a project requires a name");
        }
        Long clientId = body.getClientId();
        Client client = clientId == null ? null : clients.findById(clientId).orElse(null);
        if (client == null) {
            throw new IllegalArgumentException("a project requires an existing client");
        }
        String status = body.getStatus() == null ? "ACTIVE" : body.getStatus().trim();
        if (!status.equals("ACTIVE") && !status.equals("ON_HOLD") && !status.equals("FINISHED")) {
            throw new IllegalArgumentException("a project status must be ACTIVE, ON_HOLD or FINISHED");
        }
        Project project = new Project();
        project.setName(name);
        project.setClientId(clientId);
        project.setStatus(status);
        Project saved = projects.save(project);
        audit.record("PROJECT_CREATED id=" + saved.getId() + " name=" + saved.getName()
                + " client=" + client.getName());
        response.send(new ProjectView(saved.getId(), saved.getName(), saved.getClientId(),
                client.getName(), saved.isArchived(), saved.getStatus()));
    }
}

package net.officefloor.hq.app;

import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.web.ObjectResponse;

/**
 * {@code GET /api/projects} — list every project, oldest first, each carrying its client's NAME so
 * the UI shows the name (not the id). Wired by {@code officefloor/rest/api/projects.GET.yml}.
 */
public class ProjectsGet {

    public void service(ProjectRepository projects, ClientRepository clients,
            ObjectResponse<List<ProjectView>> response) {
        Map<Long, String> nameById = clients.findAll().stream()
                .collect(Collectors.toMap(Client::getId, Client::getName));
        List<ProjectView> views = projects.findAllByOrderByIdAsc().stream()
                .map(p -> new ProjectView(p.getId(), p.getName(), p.getClientId(),
                        nameById.get(p.getClientId()), p.isArchived(), p.getStatus()))
                .collect(Collectors.toList());
        response.send(views);
    }
}

package net.officefloor.hq.app;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.web.HttpQueryParameter;
import net.officefloor.web.ObjectResponse;

/**
 * {@code GET /api/search?q=...} — one search box across both clients and projects. Returns the
 * clients and the projects whose name contains {@code q} (case-insensitive), grouped by kind in a
 * {@link SearchView}. Archived rows are tucked away, so they drop off the search on both sides.
 * Wired by {@code officefloor/rest/api/search.GET.yml}.
 *
 * <p>When {@code q} is absent or blank there is nothing to search for, so both groups come back
 * empty rather than the whole database.
 */
public class SearchGet {

    public void service(@HttpQueryParameter("q") String q, ClientRepository clients,
            ProjectRepository projects, ObjectResponse<SearchView> response) {
        String term = q == null ? "" : q.trim();
        if (term.isEmpty()) {
            response.send(new SearchView(List.of(), List.of()));
            return;
        }

        List<Client> matchedClients =
                clients.findByArchivedFalseAndNameContainingIgnoreCaseOrderByIdAsc(term);

        // Projects carry their client's NAME (like /api/projects), so join against the client names.
        Map<Long, String> nameById = clients.findAll().stream()
                .collect(Collectors.toMap(Client::getId, Client::getName));
        List<ProjectView> matchedProjects =
                projects.findByArchivedFalseAndNameContainingIgnoreCaseOrderByIdAsc(term).stream()
                        .map(p -> new ProjectView(p.getId(), p.getName(), p.getClientId(),
                                nameById.get(p.getClientId()), p.isArchived(), p.getStatus()))
                        .collect(Collectors.toList());

        response.send(new SearchView(matchedClients, matchedProjects));
    }
}

package net.officefloor.hq.app;

import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * {@code POST /api/projects/archive} — tuck a project away instead of deleting it: flag it archived
 * so it drops off the default project lists while the row (and everything under it) is kept. Wired
 * by {@code officefloor/rest/api/projects/archive.POST.yml}. The project must exist; the archiving
 * is audited through {@link Audit} so it can be checked back later.
 */
public class ProjectsArchive {

    public void service(@RequestBody ArchiveProject body, ProjectRepository projects, Audit audit,
            ObjectResponse<ProjectView> response) {
        Long id = body.getId();
        Project project = id == null ? null : projects.findById(id).orElse(null);
        if (project == null) {
            throw new IllegalArgumentException("no such project");
        }
        project.setArchived(true);
        Project saved = projects.save(project);
        audit.record("PROJECT_ARCHIVED id=" + id);
        response.send(new ProjectView(saved.getId(), saved.getName(), saved.getClientId(), null,
                saved.isArchived(), saved.getStatus()));
    }
}

